\label{rk:identification basic observations}
Let~$(\pi,\sigma)$ identifying some subset~$S$ of~$V\setminus L$.
\begin{enumerate}
    \item\label{rk:identification basic observations:commute}
        The reversed pair $(\sigma,\pi)$ also identifies~$S$
        and has unique request whenever~$(\pi,\sigma)$ does.
    \item\label{rk:identification basic observations:sub}
        If~$S'\subset S$, then $(\pi_{|S'},\sigma_{|S'})$ identifies~$S'$,
        and has unique request if~$(\pi, \sigma)$ does.
    \item\label{rk:identification basic observations:self-request}
        For each~$s\in S$, $s$ is $s$-requested in~$(\pi,\sigma)$.
    \item\label{rk:identification basic observations:disjoint}
        If $(\sigma,\pi)$ has unique request,
        then~$\pi(S)$ and~$\sigma(S)$ are disjoint subsets of~$L$.
\end{enumerate}

We say that~$M$ is a \defd{module (of~$G$)}
if for every $u\notin M$ and every $v,w\in M$,
${uv\in E(G)\!\iff\! uw\in E(G)}$
and~${vu\in E(G)\!\iff\! wu\in E(G)}$.

